command:
$ErrorActionPreference="Stop"
$repo="C:\dev\flyExplorer"
$main="0b3ba42fe528f31fa4d6978b11d58a8f50a884c1"
$candidate="fc8712fe03eca36c766dfb1b758cde3a160958e9"
$branch="work/verification-infra-simplify-20261005"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("validation-infra-candidate-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  $env:PYTHONIOENCODING="utf-8"

  & python -X utf8 (Join-Path $temp "tools\winui\run_checks.py") source
  if($LASTEXITCODE -ne 0){throw "candidate source failed"}

  $checker=Join-Path $temp "tools\winui\check_python_static.py"
  $critical=@(
    (Join-Path $temp "tools\winui\high_contrast_state.py"),
    (Join-Path $temp "tools\winui\high_contrast_runner_setup.py"),
    (Join-Path $temp "tools\winui\high_contrast_acceptance.py"),
    (Join-Path $temp "tools\winui\runner_health.py"),
    (Join-Path $temp "tests\winui\test_high_contrast_gui.py")
  )
  & python -X utf8 $checker @critical
  if($LASTEXITCODE -ne 0){throw "critical Python static check failed"}

  & python -X utf8 (Join-Path $temp "tools\winui\high_contrast_runner_setup.py") --check
  if($LASTEXITCODE -ne 0){throw "High Contrast setup check failed"}
  & python -X utf8 (Join-Path $temp "tools\winui\runner_health.py") --configuration Release --check
  if($LASTEXITCODE -ne 0){throw "runner health check failed"}

  & git -C $temp diff --check ($main+".."+$candidate)
  if($LASTEXITCODE -ne 0){throw "candidate diff check failed"}
  Write-Host "VALIDATION_INFRA_SOURCE_AND_HEALTH_PASS"
}finally{
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
